diff --git a/internal/release/check.go b/internal/release/check.go
new file mode 100644
index 00000000..3d4854fa
--- /dev/null
+++ b/internal/release/check.go
@@ -0,0 +1,89 @@
+package release
+
+import (
+	"context"
+	"fmt"
+	"strings"
+
+	"github.com/blang/semver/v4"
+	"github.com/google/go-github/v32/github"
+)
+
+// Info contains information about the current build and the latest available release.
+type Info struct {
+	CurrentVersion   string
+	LatestVersion    string
+	LatestVersionURL string
+	UpdateAvailable  bool
+}
+
+type releaseChecker interface {
+	getLatestRelease(ctx context.Context) (*github.RepositoryRelease, error)
+}
+
+type githubReleaseChecker struct{}
+
+func (c *githubReleaseChecker) getLatestRelease(ctx context.Context) (*github.RepositoryRelease, error) {
+	client := github.NewClient(nil)
+	release, _, err := client.Repositories.GetLatestRelease(ctx, "flipt-io", "flipt")
+	if err != nil {
+		return nil, fmt.Errorf("checking for latest version: %w", err)
+	}
+
+	return release, nil
+}
+
+var defaultReleaseChecker releaseChecker = &githubReleaseChecker{}
+
+// Check returns the latest release information for the given version.
+func Check(ctx context.Context, version string) (Info, error) {
+	return check(ctx, defaultReleaseChecker, version)
+}
+
+func check(ctx context.Context, rc releaseChecker, version string) (Info, error) {
+	info := Info{
+		CurrentVersion: version,
+	}
+
+	cv, err := semver.ParseTolerant(version)
+	if err != nil {
+		return info, fmt.Errorf("parsing current version: %w", err)
+	}
+
+	release, err := rc.getLatestRelease(ctx)
+	if err != nil {
+		return info, err
+	}
+
+	if release != nil {
+		lv, err := semver.ParseTolerant(release.GetTagName())
+		if err != nil {
+			return info, fmt.Errorf("parsing latest version: %w", err)
+		}
+
+		info.LatestVersion = lv.String()
+
+		if cv.Compare(lv) < 0 {
+			info.UpdateAvailable = true
+			info.LatestVersionURL = release.GetHTMLURL()
+		}
+	}
+
+	return info, nil
+}
+
+// Is returns true if the given version is a proper release, ie not a
+// development, snapshot or release candidate build.
+func Is(version string) bool {
+	if version == "" {
+		return false
+	}
+
+	for _, s := range []string{"dev", "snapshot", "rc"} {
+		if strings.Contains(strings.ToLower(version), s) {
+			return false
+		}
+	}
+
+	return true
+}

