+
+// Expr is a node in the AST.
+type Expr interface {
+	// Kind indicates the expression kind.
+	Kind() reflect.Kind
+	// Evaluate evaluates the expression given the evaluation context.
+	Evaluate(ctx EvaluateContext) (any, error)
