+}
+
+// Kind indicates the RegexpNotMatchExpr kind.
+func (e *RegexpNotMatchExpr) Kind() reflect.Kind {
+	return reflect.Bool
+}
+
+// Evaluate evaluates the StringLitExpr given the evaluation context.
